-- Source: database/tables/007_backfill_existing_profiles.sql | normalized SHA256: 3a4b52853400f5d1b7e9a34b3296a16bde6814bade24b687454398a3c083375f
-- Covers users created before this migration, including existing Google accounts.
insert into public.profiles (id, display_name)
select
    users.id,
    nullif(pg_catalog.left(pg_catalog.btrim(
        coalesce(users.raw_user_meta_data ->> 'full_name', users.raw_user_meta_data ->> 'name', '')
    ), 120), '')
from auth.users as users
on conflict (id) do nothing;

