-- Account-scoped completion; clients cannot reset or forge its timestamp.
alter table public.profiles add column if not exists onboarding_completed_at timestamptz;
grant select (onboarding_completed_at) on public.profiles to authenticated;

-- Source: database/functions/009_complete_onboarding.sql | normalized SHA256: b9347de44cd57a1f13030fa880e6f35bd8a2337e273096b59dc59c836ab8982d
create or replace function public.complete_onboarding()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare actor uuid := auth.uid();
begin
    if actor is null then
        raise exception 'Authentication required' using errcode = '42501';
    end if;
    update public.profiles
    set onboarding_completed_at = pg_catalog.now()
    where id = actor and onboarding_completed_at is null;
    if not found and not exists (select 1 from public.profiles where id = actor) then
        raise exception 'Profile unavailable' using errcode = 'P0002';
    end if;
end;
$$;
revoke all on function public.complete_onboarding() from public, anon, authenticated;
grant execute on function public.complete_onboarding() to authenticated;

commit;
